"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8511],{50142:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PermissionsConfig","desc":"Who holds which permission. Every table is keyed by permission label, such\\nas \\"cmdr\\", except `Admins`. Edit the values in this module to set up\\npermissions for a project.\\n\\nA check resolves in this order, and the first rule that applies wins:\\n1. A runtime grant or revoke from `PermissionService:SetRuntimePermission()`\\n2. `UserDeniedPermissions`\\n3. `Admins`, then the test player and Studio settings\\n4. `UserPermissions`\\n5. `GroupPermissions`, checked with `GroupService:GetRolesInGroupAsync()`","source":{"line":25,"path":"src/shared/core/lib/PermissionsConfig.luau"}}')}}]);